def solution(input_data=None):
    import sys

    if input_data is None:
        data = sys.stdin.read().strip().split()
    else:
        data = str(input_data).strip().split()

    x = int(data[0])
    hh = int(data[1])
    mm = int(data[2])

    def unlucky(h, m):
        s = f"{h:02d}{m:02d}"
        return '7' not in s

    y = 0
    while True:
        total = (hh * 60 + mm) - x * y
        total %= (24 * 60)
        h = total // 60
        m = total % 60
        if unlucky(h, m):
            if input_data is None:
                print(y)
            return y
        y += 1
